model:
var y pi i;
varexo ey epi ei;
parameters sigma beta kappa phi_pi phi_y;
sigma = 1; beta = 0.99; kappa = 0.1; phi_pi = 1.5; phi_y = 0.5;
model(linear);
y = y(+1) - (1/sigma)*(i - pi(+1)) + ey;
pi = beta*pi(+1) + kappa*y + epi;
i = phi_pi*pi + phi_y*y + ei;
end;
shocks; var ey; stderr 0.5; var epi; stderr 0.3; var ei; stderr 0.2; end;
estimated_params;
phi_pi, uniform_pdf, , , 0, 2;
phi_y, uniform_pdf, , , 0, 1;
end;
varobs y pi i;
sensitivity(stab=1, Nsam=2000, redform=0, identification=0, graph_format=none, nodisplay);
